# Keep this source file ASCII-only. Windows PowerShell 5.1 decodes BOM-less scripts
# through the active ANSI code page; non-ASCII HTML/JavaScript can corrupt markup
# and JavaScript syntax on non-English Windows hosts.
function Get-MihariManagementUiHtml {
    [CmdletBinding()]
    param(
        [AllowNull()][string] $ControlToken = ''
    )

    $html = @'
<!doctype html>
<html lang="en">
