    .activity-header{display:flex;align-items:center;gap:8px}.refresh-label{font-size:10px;color:var(--muted);font-weight:500}.table-wrap{overflow:auto}.activity-table{border-collapse:collapse;width:100%;font-size:11px}.activity-table th{text-align:left;color:#8290a2;text-transform:uppercase;letter-spacing:.075em;font-size:9px;font-weight:700;padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap}.activity-table td{padding:10px 12px;border-bottom:1px solid #f0f3f7;vertical-align:top}.activity-table tr:last-child td{border-bottom:0}.event-stage{font-weight:700;color:#40536f;white-space:nowrap}.event-target{max-width:210px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#263950}.event-outcome{font-weight:700}.event-outcome.success{color:var(--teal)}.event-outcome.failed,.event-outcome.error,.event-outcome.rejected{color:var(--red)}.event-outcome.unsupported,.event-outcome.timeout{color:var(--amber)}.event-time{white-space:nowrap;color:#758399;font-variant-numeric:tabular-nums}.empty{padding:27px 16px;text-align:center;color:#8995a5;font-size:11px}.loading{color:#8995a5}.findings-list{display:grid}.finding{padding:12px 16px;border-bottom:1px solid #f0f3f7;display:grid;grid-template-columns:26px minmax(0,1fr);gap:10px}.finding:last-child{border-bottom:0}.finding-mark{width:25px;height:25px;border-radius:7px;background:var(--amber2);color:var(--amber);display:grid;place-items:center;font-weight:800;font-size:12px}.finding-mark.red{background:var(--red2);color:var(--red)}.finding-title{font-size:11px;font-weight:700;line-height:1.4}.finding-code{font:10px Consolas,"SFMono-Regular",monospace;color:#7c899b;margin-top:3px}.finding-meta{font-size:10px;color:var(--muted);margin-top:4px;line-height:1.4}.connection-list{display:grid}.connection-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:12px;align-items:center;padding:11px 16px;border-bottom:1px solid #f0f3f7;font-size:11px}.connection-row:last-child{border-bottom:0}.connection-target{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.connection-sub{font-size:10px;color:var(--muted);margin-top:2px}.connection-mode{font-size:9px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#63738a;background:#f0f3f7;padding:4px 7px;border-radius:5px}.error-bar{display:none;margin-top:18px;padding:11px 14px;border:1px solid #f1ced2;background:#fff5f5;color:#91434c;border-radius:8px;font-size:11px}.error-bar.visible{display:flex;align-items:flex-start;gap:9px}.error-icon{font-weight:900}.footer{display:flex;justify-content:space-between;align-items:center;color:#8793a3;font-size:10px;margin-top:17px;padding:0 2px}.footer span{display:flex;gap:6px;align-items:center}.pulse{animation:pulse 1.8s infinite}@keyframes pulse{0%,100%{opacity:1}50%{opacity:.45}}
    @media(max-width:900px){.layout{grid-template-columns:1fr}.side{grid-row:1}.side .control-card{max-width:none}.runtime{grid-template-columns:repeat(3,minmax(0,1fr))}}
    @media(max-width:620px){.topbar{padding:0 16px;height:60px}.topmeta{gap:9px}.topmeta .hide-small{display:none}main{padding:23px 14px 38px}.page-head{display:block}.session-chip{margin-top:16px;width:max-content;max-width:100%}.runtime{grid-template-columns:1fr 1fr}.overview-stat{padding:13px}.overview-value{font-size:16px}.details{gap:13px}.activity-table th:nth-child(3),.activity-table td:nth-child(3){display:none}.card-head{padding-left:15px;padding-right:15px}.card-body{padding-left:15px;padding-right:15px}.connection-row{grid-template-columns:minmax(0,1fr) auto;gap:6px 10px}.connection-row .event-time{grid-column:1}.connection-row .connection-mode{grid-column:2;grid-row:1 / span 2}.footer{align-items:flex-start;gap:12px;flex-direction:column}}
    @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}
    [hidden]{display:none!important}.workspace-nav{display:flex;gap:7px;margin:0 0 17px;padding:4px;background:#e8edf5;border-radius:9px;width:max-content;max-width:100%}.workspace-tab{border:0;background:transparent;color:#5d6c82;border-radius:6px;padding:8px 13px;font-size:11px;font-weight:700}.workspace-tab[aria-selected="true"]{background:#fff;color:var(--ink);box-shadow:0 1px 4px rgba(24,44,75,.12)}.workspace-tab:focus-visible,.traffic-input:focus-visible,.traffic-select:focus-visible,.traffic-button:focus-visible,.traffic-row:focus-visible{outline:3px solid #94b6ff;outline-offset:2px}
    .traffic-stack{display:grid;gap:15px;min-width:0}.traffic-title-row{display:flex;justify-content:space-between;align-items:flex-start;gap:14px}.traffic-title-row h2{font-size:17px;margin:0}.traffic-title-row p{margin:4px 0 0;font-size:11px;color:var(--muted)}.traffic-actions{display:flex;gap:7px;align-items:center}.traffic-button{min-height:32px;border:1px solid #d7e0ec;background:#fff;color:#334760;border-radius:6px;padding:6px 10px;font-size:10px;font-weight:700}.traffic-button:hover{background:#f5f8fc}.traffic-button-primary{background:var(--blue);border-color:var(--blue);color:#fff}.traffic-button-primary:hover{background:#1d55c1}.traffic-button:disabled{cursor:not-allowed}.traffic-meta{display:flex;flex-wrap:wrap;gap:7px;margin-top:12px}.traffic-meta .pill{font-size:9px}.traffic-controls{display:grid;grid-template-columns:repeat(4,minmax(125px,1fr));gap:10px 12px}.traffic-field{min-width:0}.traffic-field label{display:block;font-size:9px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);font-weight:700;margin-bottom:4px}.traffic-input,.traffic-select{width:100%;height:32px;border:1px solid #dce4ef;border-radius:6px;padding:0 8px;background:#fff;color:var(--ink);font-size:11px;min-width:0}.traffic-saved{display:flex;gap:7px;align-items:end;flex-wrap:wrap;border-top:1px solid #edf0f5;padding-top:12px;margin-top:13px}.traffic-saved .traffic-field{width:190px;max-width:100%}.traffic-status{font-size:10px;color:var(--muted);margin-left:auto;align-self:center}.traffic-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.85fr);gap:15px;align-items:start}.traffic-table-wrap{overflow:auto;max-height:620px}.traffic-table{border-collapse:collapse;width:100%;min-width:880px;font-size:10px}.traffic-table th{text-align:left;color:#8290a2;text-transform:uppercase;letter-spacing:.065em;font-size:8px;padding:9px 8px;border-bottom:1px solid var(--line);white-space:nowrap;position:sticky;top:0;background:#fff;z-index:1}.traffic-table td{padding:9px 8px;border-bottom:1px solid #f0f3f7;vertical-align:top}.traffic-row{cursor:pointer}.traffic-row:hover{background:#f7f9fc}.traffic-row.selected{background:#eaf1ff}.traffic-cell-time,.traffic-cell-duration{white-space:nowrap;color:#758399;font-variant-numeric:tabular-nums}.traffic-cell-target{max-width:245px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#263950}.traffic-cell-target strong{font-weight:700}.traffic-cell-sub{font-size:9px;color:var(--muted);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.traffic-source{color:#586b86}.traffic-stale{color:var(--amber);font-weight:700}.traffic-empty{padding:24px 14px;text-align:center;color:#8995a5;font-size:11px}.traffic-error{display:none;border:1px solid #f1ced2;background:#fff5f5;color:#91434c;border-radius:7px;padding:9px 11px;font-size:10px}.traffic-error.visible{display:block}.detail-panel{position:sticky;top:12px;max-height:calc(100vh - 24px);overflow:auto}.detail-summary{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:13px 15px;border-bottom:1px solid #edf0f5}.detail-item{min-width:0}.detail-item.wide{grid-column:1/-1}.detail-item label{display:block;color:var(--muted);font-size:8px;text-transform:uppercase;letter-spacing:.08em;font-weight:700}.detail-item span{display:block;margin-top:3px;font-size:10px;font-weight:600;overflow-wrap:anywhere}.detail-section{padding:12px 15px;border-bottom:1px solid #edf0f5}.detail-section:last-child{border-bottom:0}.detail-section h3{font-size:10px;text-transform:uppercase;letter-spacing:.07em;color:#5d6b7f;margin:0 0 8px}.detail-note{font-size:9px;color:var(--muted);margin:0 0 8px}.timeline{display:grid;gap:6px}.timeline-item{display:grid;grid-template-columns:9px minmax(0,1fr) auto;gap:8px;align-items:start;font-size:9px}.timeline-mark{width:7px;height:7px;border-radius:50%;background:#7187a6;margin-top:4px}.timeline-item.failed .timeline-mark{background:var(--red)}.timeline-item.success .timeline-mark{background:var(--teal)}.timeline-stage{font-weight:700;color:#40536f;overflow-wrap:anywhere}.timeline-meta{color:var(--muted);margin-top:2px;overflow-wrap:anywhere}.evidence-event{border:1px solid #e5eaf1;border-radius:6px;margin:5px 0;background:#fff}.evidence-event summary{cursor:pointer;list-style:none;padding:7px 9px;font-size:9px;font-weight:700;display:flex;justify-content:space-between;gap:8px}.evidence-event summary::-webkit-details-marker{display:none}.evidence-body{padding:0 9px 8px}.evidence-kv{display:grid;grid-template-columns:minmax(78px,.55fr) minmax(0,1fr);gap:4px 8px;font-size:9px}.evidence-kv dt{color:var(--muted);overflow-wrap:anywhere}.evidence-kv dd{margin:0;overflow-wrap:anywhere}.evidence-id{font:9px Consolas,"SFMono-Regular",monospace;color:#64738a}.linked-ref{font-size:9px;margin:4px 0;color:#40536f;overflow-wrap:anywhere}.traffic-more{display:flex;justify-content:center;padding:10px;border-top:1px solid #edf0f5}.unknown{color:#8290a2;font-style:italic}
    @media(max-width:1050px){.traffic-grid{grid-template-columns:1fr}.detail-panel{position:static;max-height:none}.traffic-table-wrap{max-height:480px}}
    @media(max-width:720px){.traffic-controls{grid-template-columns:repeat(2,minmax(120px,1fr))}.traffic-title-row{display:block}.traffic-actions{margin-top:10px}.traffic-status{margin-left:0;width:100%}.traffic-saved .traffic-field{width:calc(50% - 5px);flex:1}.workspace-nav{width:100%}.workspace-tab{flex:1}}
    .waterfall-row{display:grid;grid-template-columns:90px minmax(40px,1fr) 52px;gap:8px;align-items:center;margin:5px 0;font-size:9px}.waterfall-row>span:first-child{color:#536278;overflow-wrap:anywhere}.waterfall-track{height:8px;position:relative;background:#f0f3f8;border-radius:5px}.waterfall-track i{position:absolute;top:0;bottom:0;border-radius:5px;background:#5b8be2}.error-dismiss{margin-left:auto;border:0;background:transparent;color:inherit;text-decoration:underline;font-size:10px;font-weight:700;padding:0 5px}
  </style>
</head>
<body>
  <header class="topbar">
    <div class="brand">
      <div class="logo" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path d="M4 16.5 9.2 7l3.1 5.3L15 7l5 9.5M6 16.5h12" stroke="white" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/><circle cx="9.2" cy="7" r="1.2" fill="white"/><circle cx="15" cy="7" r="1.2" fill="white"/></svg></div>
      <div><div class="brand-name">Mihari</div><div class="brand-sub">Local diagnostics</div></div>
    </div>
    <div class="topmeta"><span><i class="live-dot" id="top-live"></i><b id="top-status">Connecting</b></span><span class="hide-small">Refreshes automatically</span></div>
  </header>
  <main>
    <div class="page-head">
      <div><div class="eyebrow">Session console</div><h1>Network diagnostics</h1><p>Observe proxy activity and compare Inspect with Tunnel as you reproduce an issue.</p></div>
      <div class="session-chip"><span>SESSION</span><strong id="session-id">Loading...</strong></div>
    </div>
    <nav class="workspace-nav" role="tablist" aria-label="Diagnostic workspaces">
      <button class="workspace-tab" id="tab-overview" type="button" role="tab" aria-selected="true" aria-controls="overview-view">Overview</button>
      <button class="workspace-tab" id="tab-traffic" type="button" role="tab" aria-selected="false" aria-controls="traffic-view">Traffic Inspector</button>
      <button class="workspace-tab" type="button" role="tab" aria-disabled="true" disabled title="This workspace is not available from the current management API">Dependencies</button>
      <button class="workspace-tab" type="button" role="tab" aria-disabled="true" disabled title="This workspace is not available from the current management API">Diagnostics</button>
      <button class="workspace-tab" type="button" role="tab" aria-disabled="true" disabled title="This workspace is not available from the current management API">TLS &amp; Certificates</button>
      <button class="workspace-tab" type="button" role="tab" aria-disabled="true" disabled title="This workspace is not available from the current management API">Environment</button>
      <button class="workspace-tab" type="button" role="tab" aria-disabled="true" disabled title="This workspace is not available from the current management API">Compare</button>
      <button class="workspace-tab" type="button" role="tab" aria-disabled="true" disabled title="This workspace is not available from the current management API">Evidence</button>
    </nav>
    <section class="workspace-view" id="overview-view" role="tabpanel" aria-labelledby="tab-overview">
    <div class="layout">
      <div class="stack">
        <section class="card" aria-labelledby="overview-title">
          <div class="card-head"><div><div class="card-title" id="overview-title">Runtime overview</div><div class="card-note">Live state of this Mihari session</div></div><span class="pill neutral" id="runtime-pill">Checking</span></div>
          <div class="overview-strip">
            <div class="overview-stat"><div class="mini-label">Session mode</div><div class="overview-value" id="overview-mode">-</div><div class="overview-caption" id="overview-mode-caption">New connections use this mode</div></div>
            <div class="overview-stat"><div class="mini-label">Open connections</div><div class="overview-value" id="active-count">-</div><div class="overview-caption">Currently handled by Mihari</div></div>
            <div class="overview-stat"><div class="mini-label">Findings</div><div class="overview-value" id="finding-count">-</div><div class="overview-caption">Zero findings does not prove traffic is healthy</div></div>
          </div>
          <div class="card-body"><div class="runtime">
            <div class="runtime-tile"><div class="runtime-top"><span class="runtime-title">Proxy listener</span><span class="runtime-icon"><svg viewBox="0 0 20 20" fill="none"><path d="M3 5.5h14v9H3zM6 8h.01M9 8h.01M6 11h8" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></span></div><div class="runtime-value" id="proxy-endpoint">-</div><div class="runtime-meta" id="proxy-health">Waiting for listener</div></div>
