      var rt=routeText(get(data,['upstreamRoute','upstream','route']));set('upstream-value',rt.main);set('upstream-meta',rt.meta||'Selected independently from the diagnostic browser proxy');set('upstream-pill',rt.main==='Route not reported'?'Route pending':'Route observed');el('upstream-pill').className='pill '+(rt.main==='Route not reported'?'neutral':'good');
