      renderTransportLegs(root,record,events);
      var relations=[];['redirects','retries','relationships'].forEach(function(name){var values=get(record,[name]);if(Array.isArray(values))relations=relations.concat(values);else if(values)relations.push(values);});if(relations.length){var rel=document.createElement('section');rel.className='detail-section';var relTitle=document.createElement('h3');relTitle.textContent='Redirects and retries';rel.appendChild(relTitle);relations.forEach(function(edge){var row=document.createElement('div');row.className='linked-ref';var kind=text(get(edge,['kind','type']),'relationship');var confidence=text(get(edge,['confidence','edgeType']),'unknown basis');var dest=get(edge,['target','destination','url']);row.textContent=kind+' ('+confidence+')'+(dest?' - '+safeEvidenceLocation(dest):'');rel.appendChild(row);});root.appendChild(rel);}
      var refs=get(payload,['evidence','evidenceRefs','references'])||[];if(!Array.isArray(refs))refs=[refs];refs=refs.slice(0,200);var evidence=document.createElement('section');evidence.className='detail-section';var evidenceTitle=document.createElement('h3');evidenceTitle.textContent='Linked evidence';evidence.appendChild(evidenceTitle);events.forEach(function(event,index){var evidenceKey=eventKey(event)||('evidence-index:'+index);renderEventEvidence(evidence,event,previouslyOpen[evidenceKey]===true,index);});refs.forEach(function(ref){var row=document.createElement('div');row.className='linked-ref';row.textContent='Evidence '+text(get(ref,['sessionId']),'session unknown')+' / '+text(get(ref,['eventId']),'event id unknown')+' - '+text(get(ref,['edgeType','kind','relationship']),'reference');evidence.appendChild(row);});if(!events.length&&!refs.length){var none=document.createElement('div');none.className='unknown';none.textContent='No evidence references were returned.';evidence.appendChild(none);}root.appendChild(evidence);if(preserveExpanded)el('request-detail').scrollTop=scroll;set('detail-subtitle','Selected request evidence; fields are limited to returned safe facts.');el('copy-request-key').disabled=!trafficSelectedKey;el('toggle-bookmark').disabled=!trafficSelectedKey;updateBookmarkButton();}
    function selectRequest(key){if(!key)return;trafficSelectedKey=key;trafficDetailPayload=null;setTrafficError('','detail');renderTrafficRows();set('detail-subtitle','Loading request '+key);el('detail-content').textContent='';el('copy-request-key').disabled=false;el('toggle-bookmark').disabled=false;updateBookmarkButton();var serial=++detailRequestSerial;trafficDetailBusy=true;request(API.requestDetail+encodeURIComponent(key)).then(function(payload){if(serial!==detailRequestSerial)return;trafficDetailPayload=payload;renderRequestDetail(payload,false);setTrafficError('','detail');}).catch(function(error){if(serial!==detailRequestSerial)return;set('detail-subtitle','Request detail is stale or unavailable.');var message=document.createElement('div');message.className='traffic-empty';message.textContent='The management API could not load this request detail: '+text(error&&error.message,'detail query failed');el('detail-content').appendChild(message);setTrafficError('Request detail is stale because the management API failed: '+text(error&&error.message,'detail query failed'),'detail');}).finally(function(){if(serial===detailRequestSerial)trafficDetailBusy=false;});}
    function refreshSelectedDetail(){if(!trafficSelectedKey||trafficDetailBusy)return;var serial=++detailRequestSerial;trafficDetailBusy=true;request(API.requestDetail+encodeURIComponent(trafficSelectedKey)).then(function(payload){if(serial!==detailRequestSerial)return;trafficDetailPayload=payload;renderRequestDetail(payload,true);setTrafficError('','detail');}).catch(function(error){if(serial===detailRequestSerial){set('detail-subtitle','Selected detail is stale; the last successful evidence remains visible.');setTrafficError('Selected request detail is stale because the management API failed: '+text(error&&error.message,'detail query failed'),'detail');}}).finally(function(){if(serial===detailRequestSerial)trafficDetailBusy=false;});}

    function isBookmarked(key){return !!key&&bookmarks.indexOf(key)>=0;}
    function updateBookmarkButton(){var button=el('toggle-bookmark');var saved=isBookmarked(trafficSelectedKey);button.textContent=saved?'Remove bookmark':'Bookmark';button.title='Browser-local only; this does not change evidence';}
    function loadBookmarks(){try{var raw=window.localStorage.getItem(bookmarkStorage);var values=raw?JSON.parse(raw):[];bookmarks=[];if(Array.isArray(values))values.slice(0,500).forEach(function(value){if(typeof value==='string'&&value.length<=512&&bookmarks.indexOf(value)<0)bookmarks.push(value);});}catch(error){bookmarks=[];set('detail-subtitle','Browser-local bookmarks are unavailable: '+text(error&&error.message,'storage unavailable'));}}
    function toggleBookmark(){if(!trafficSelectedKey)return;var index=bookmarks.indexOf(trafficSelectedKey);if(index>=0)bookmarks.splice(index,1);else if(bookmarks.length<500)bookmarks.push(trafficSelectedKey);else{set('detail-subtitle','The browser-local bookmark limit is 500 request keys.');return;}try{window.localStorage.setItem(bookmarkStorage,JSON.stringify(bookmarks));set('detail-subtitle',isBookmarked(trafficSelectedKey)?'Bookmarked in this browser profile; evidence is unchanged.':'Bookmark removed from this browser profile.');}catch(error){set('detail-subtitle','Bookmark state is only available until this page closes: '+text(error&&error.message,'storage unavailable'));}updateBookmarkButton();renderTrafficRows();}
    function savedFilterValues(){var values={};Object.keys(trafficFilterIds).forEach(function(key){values[key]=String(el(trafficFilterIds[key]).value||'').slice(0,512);});return values;}
    function normalizeSavedViews(value){var normalized=[];if(!Array.isArray(value))return normalized;value.slice(0,20).forEach(function(view){if(!view||typeof view.name!=='string'||!view.name.trim()||!view.filters||typeof view.filters!=='object')return;var filters={};Object.keys(trafficFilterIds).forEach(function(key){if(typeof view.filters[key]==='string')filters[key]=view.filters[key].slice(0,512);});normalized.push({id:String(view.id||normalized.length).slice(0,64),name:view.name.trim().slice(0,48),filters:filters});});return normalized;}
    function saveViews(){try{window.localStorage.setItem(savedViewStorage,JSON.stringify(savedViews));set('saved-view-status','Saved views stay in this browser profile.');}catch(error){set('saved-view-status','This browser could not save local views: '+text(error&&error.message,'storage unavailable'));}}
    function populateSavedViews(selected){var select=el('saved-views');select.textContent='';var prompt=document.createElement('option');prompt.value='';prompt.textContent='Choose a saved view';select.appendChild(prompt);savedViews.forEach(function(view){var option=document.createElement('option');option.value=view.id;option.textContent=view.name;select.appendChild(option);});if(selected)select.value=selected;}
    function loadSavedViews(){try{var raw=window.localStorage.getItem(savedViewStorage);savedViews=normalizeSavedViews(raw?JSON.parse(raw):[]);}catch(error){savedViews=[];set('saved-view-status','Saved views are unavailable in this browser profile.');}populateSavedViews('');}
    function clearTrafficResults(){trafficItems=[];trafficCursor=null;trafficPage=1;trafficRevision=null;renderTrafficRows();el('load-more').disabled=true;}
    function scheduleTrafficQuery(){if(trafficDebounce)window.clearTimeout(trafficDebounce);trafficQuerySerial++;trafficDebounce=window.setTimeout(function(){trafficDebounce=null;trafficCursor=null;clearTrafficResults();refreshTraffic(false);},250);}
    function openWorkspace(name){var traffic=name==='traffic';trafficActive=traffic;el('overview-view').hidden=traffic;el('traffic-view').hidden=!traffic;el('tab-overview').setAttribute('aria-selected',traffic?'false':'true');el('tab-traffic').setAttribute('aria-selected',traffic?'true':'false');if(traffic&&!trafficPaused)refreshTraffic(false);}
    function initTrafficInspector(){el('tab-overview').addEventListener('click',function(){openWorkspace('overview');});el('tab-traffic').addEventListener('click',function(){openWorkspace('traffic');});Object.keys(trafficFilterIds).forEach(function(key){var input=el(trafficFilterIds[key]);input.addEventListener('input',scheduleTrafficQuery);input.addEventListener('change',scheduleTrafficQuery);});el('traffic-refresh').addEventListener('click',function(){refreshTraffic(false);});el('load-more').addEventListener('click',function(){refreshTraffic(true);});el('traffic-pause').addEventListener('click',function(){trafficPaused=!trafficPaused;trafficQuerySerial++;this.setAttribute('aria-pressed',trafficPaused?'true':'false');this.textContent=trafficPaused?'Resume live':'Pause display';el('traffic-display-state').className='traffic-status'+(trafficPaused?' traffic-stale':'');el('traffic-display-state').textContent=trafficPaused?'Display paused; capture continues':'Live display; capture continues';if(!trafficPaused)refreshTraffic(false);});el('clear-filters').addEventListener('click',function(){Object.keys(trafficFilterIds).forEach(function(key){el(trafficFilterIds[key]).value='';});el('saved-views').value='';scheduleTrafficQuery();});el('save-view').addEventListener('click',function(){var name=el('saved-view-name').value.trim();if(!name){set('saved-view-status','Enter a name for this view.');el('saved-view-name').focus();return;}if(savedViews.length>=20){set('saved-view-status','Remove a saved view before adding another.');return;}var view={id:String(Date.now())+'-'+String(Math.floor(Math.random()*1000000)),name:name.slice(0,48),filters:savedFilterValues()};savedViews.push(view);saveViews();populateSavedViews(view.id);el('saved-view-name').value='';});el('delete-view').addEventListener('click',function(){var id=el('saved-views').value;if(!id){set('saved-view-status','Choose a saved view to delete.');return;}savedViews=savedViews.filter(function(view){return view.id!==id;});saveViews();populateSavedViews('');});el('saved-views').addEventListener('change',function(){var view=null;for(var i=0;i<savedViews.length;i++)if(savedViews[i].id===this.value)view=savedViews[i];if(!view)return;Object.keys(trafficFilterIds).forEach(function(key){el(trafficFilterIds[key]).value=view.filters[key]||'';});scheduleTrafficQuery();});el('copy-request-key').addEventListener('click',function(){if(!trafficSelectedKey)return;var key=trafficSelectedKey;if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(key).then(function(){set('detail-subtitle','Request key copied.');}).catch(function(error){set('detail-subtitle','Could not copy request key: '+text(error&&error.message,'clipboard unavailable'));});}else{set('detail-subtitle','Clipboard access is unavailable; select the request key in the summary.');}});loadSavedViews();}
    initTrafficInspector();loadBookmarks();el('toggle-bookmark').addEventListener('click',toggleBookmark);
    refresh();window.setInterval(refresh,2500);
  })();
  </script>
</body>
</html>
'@
    $tokenJson = ConvertTo-Json -InputObject ([string]$ControlToken) -Compress
    return $html.Replace('__MIHARI_CONTROL_TOKEN__', [string]$tokenJson)
}
